const body = ($('Webhook').first().json.body) || {};
const ai = body.ai || {};
const event = body.event || {};
const eventType = String(event.type || '').toLowerCase();
if (eventType !== 'dm' && eventType !== 'comment') throw new Error('instagram_event_type_invalid');
const policy = body.policy || {};
const source = { channel: 'INSTAGRAM', eventType, occurredAt: String(event.occurredAt || ''), accountRef: String(event.accountRef || ''), postRef: String(event.postRef || ''), campaignRef: String(event.campaignRef || ''), landingPageRef: String(event.landingPageRef || '') };
const history = Array.isArray(body.history) ? body.history.slice(-20) : [];
const rules = eventType === 'comment'
  ? 'Voce esta analisando um comentario publico do Instagram. Nunca prometa publicacao automatica. Se houver risco, dado pessoal, reclamacao ou duvida comercial complexa, marque needs_human=true. A entrega final sera decidida pelo Go.'
  : 'Voce esta fazendo o primeiro atendimento de uma DM do Instagram. Colete o necessario com naturalidade e marque needs_human=true quando for hora de transferir.';
const systemPrompt = [String(ai.systemPrompt || '').trim(), rules].filter(Boolean).join('\n\n');
const userPrompt = ['Contexto de origem autoritativo: ' + JSON.stringify(source), 'Politica: ' + JSON.stringify({ autoReplyDM: policy.autoReplyDM === true, autoReplyComments: policy.autoReplyComments === true, requireCommentApproval: policy.requireCommentApproval !== false }), 'Historico: ' + JSON.stringify(history), 'Mensagem atual: ' + String(event.text || '')].join('\n');
return [{ json: { ai: { provider: ai.provider, model: ai.model, baseUrl: ai.baseUrl, temperature: ai.temperature, systemPrompt, userPrompt, schema: ai.schema }, source } }];

let r = $input.first().json || {};
if (Array.isArray(r)) r = r[0] || {};
if (r.error || r.ok !== true) return [{ json: { ok: false, errorCode: 'brain_unavailable', deliveryPolicy: 'go_outbox_only' } }];
return [{ json: { ok: true, output: r.output || null, model: String(r.model || ''), usage: r.usage || { promptTokens: 0, completionTokens: 0, totalTokens: 0 }, deliveryPolicy: 'go_outbox_only' } }];
